'use client';

import { useEffect, useRef } from 'react';
import gsap from 'gsap';
import SplitType from 'split-type';

const expertiseCards = [
    { title: 'Marketing', img: '/assets/expertise/01.jpg' },
    { title: 'Branding', img: '/assets/expertise/02.jpg' },
    { title: 'Strategy', img: '/assets/expertise/03.jpg' },
    { title: 'Content', img: '/assets/expertise/04.jpg' },
    { title: 'Analytics', img: '/assets/expertise/05.jpg' },
];

export default function ExpertiseSection() {
    const sliderRef = useRef<HTMLDivElement>(null);
    const isAnimating = useRef(false);
    const autoPlayRef = useRef<ReturnType<typeof setInterval> | null>(null);

    function initializeCards() {
        if (!sliderRef.current) return;
        const cards = Array.from(sliderRef.current.querySelectorAll('.zc-card'));
        gsap.to(cards, {
            y: (i: number) => `${-15 + 15 * i}%`,
            z: (i: number) => 15 * i,
            opacity: 1,
            duration: 1,
            ease: 'power3.out',
            stagger: -0.1,
        });
    }

    function cycleCard() {
        if (isAnimating.current || !sliderRef.current) return;
        isAnimating.current = true;

        const cards = Array.from(sliderRef.current.querySelectorAll('.zc-card'));
        const lastCard = cards.pop();
        const nextCard = cards[cards.length - 1];
        if (!lastCard) return;

        gsap.to(lastCard.querySelectorAll('.char'), {
            y: 200, duration: 0.75, ease: 'power3.in',
        });

        gsap.to(lastCard, {
            y: '+=150%', duration: 0.75, ease: 'power3.in',
            onComplete: () => {
                sliderRef.current?.prepend(lastCard);
                initializeCards();
                gsap.set(lastCard.querySelectorAll('.char'), { y: -200 });
                setTimeout(() => { isAnimating.current = false; }, 800);
            },
        });

        if (nextCard) {
            gsap.to(nextCard.querySelectorAll('.char'), {
                y: 0, duration: 1, ease: 'power3.out', stagger: 0.05,
            });
        }
    }

    function startAutoPlay() {
        if (autoPlayRef.current) clearInterval(autoPlayRef.current);
        autoPlayRef.current = setInterval(cycleCard, 2000);
    }

    useEffect(() => {
        if (!sliderRef.current) return;

        // Split text
        sliderRef.current.querySelectorAll('.zc-copy h1').forEach((h1) => {
            new SplitType(h1 as HTMLElement, { types: 'chars' });
        });

        initializeCards();

        // Initial state
        gsap.set('.zc-copy h1 .char', { y: -200 });
        const lastCard = sliderRef.current.querySelector('.zc-card:last-child');
        if (lastCard) {
            gsap.set(lastCard.querySelectorAll('.zc-copy h1 .char'), { y: 0 });
        }

        startAutoPlay();

        return () => {
            if (autoPlayRef.current) clearInterval(autoPlayRef.current);
        };
    }, []);

    const handleClick = () => {
        cycleCard();
        startAutoPlay();
    };

    return (
        <section className="zc-expertise" id="expertise">
            <h2 className="zc-section-label">Our Expertise</h2>
            <div className="zc-slider" ref={sliderRef} onClick={handleClick}>
                {expertiseCards.map((card, i) => (
                    <div className="zc-card" key={i}>
                        <img src={card.img} alt={card.title} />
                        <div className="zc-copy">
                            <h1>{card.title}</h1>
                        </div>
                    </div>
                ))}
            </div>
        </section>
    );
}

'use client';

import { useEffect, useRef } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

interface MarqueeRow {
    items: { type: 'img' | 'text'; src?: string; text?: string }[];
}

interface MarqueeSectionProps {
    title: string;
    id: string;
    rows: MarqueeRow[];
    className?: string;
}

export default function MarqueeSection({ title, id, rows, className = '' }: MarqueeSectionProps) {
    const sectionRef = useRef<HTMLElement>(null);

    useEffect(() => {
        if (!sectionRef.current) return;

        const containers = sectionRef.current.querySelectorAll('.zc-marquee-container');
        const triggers: ScrollTrigger[] = [];

        containers.forEach((container, index) => {
            const marquee = container.querySelector('.zc-marquee');
            if (!marquee) return;
            const direction = index % 2 === 0 ? -1 : 1;

            const anim = gsap.to(marquee, {
                x: direction * 600,
                ease: 'none',
                scrollTrigger: {
                    trigger: container,
                    start: 'top bottom',
                    end: 'bottom top',
                    scrub: 0.5,
                },
            });
            if (anim.scrollTrigger) triggers.push(anim.scrollTrigger);
        });

        return () => {
            triggers.forEach(t => t.kill());
        };
    }, []);

    return (
        <section className={`zc-showcase-section ${className}`} id={id} ref={sectionRef}>
            <h2 className="zc-section-label">{title}</h2>
            <div className="zc-marquees">
                {rows.map((row, ri) => (
                    <div className="zc-marquee-container" key={ri}>
                        <div className="zc-marquee">
                            {row.items.map((item, ii) => (
                                item.type === 'img' ? (
                                    <div className="zc-item" key={ii}>
                                        <img src={item.src} alt="" />
                                    </div>
                                ) : (
                                    <div className="zc-item zc-with-text" key={ii}>
                                        <h1>{item.text}</h1>
                                    </div>
                                )
                            ))}
                            {/* Duplicate for seamless loop */}
                            {row.items.map((item, ii) => (
                                item.type === 'img' ? (
                                    <div className="zc-item" key={`dup-${ii}`}>
                                        <img src={item.src} alt="" />
                                    </div>
                                ) : (
                                    <div className="zc-item zc-with-text" key={`dup-${ii}`}>
                                        <h1>{item.text}</h1>
                                    </div>
                                )
                            ))}
                        </div>
                    </div>
                ))}
            </div>
        </section>
    );
}

'use client';

import { useEffect, useRef, useState } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const reelsWorks = [
    { title: "SK Telecom :/Addiction", thumb: "https://images.prismic.io/alcre/aFNobrNJEFaPYFhr_1.png?auto=format,compress" },
    { title: "SK Telecom :/Dopamine", thumb: "https://images.prismic.io/alcre/aFNojLNJEFaPYFhs_2.png?auto=format,compress" },
    { title: "GALAXY S24", thumb: "https://images.prismic.io/alcre/aFNouLNJEFaPYFht_3.png?auto=format,compress" },
    { title: "GALAXY Z 6", thumb: "https://images.prismic.io/alcre/aFNpF7NJEFaPYFhy_4.png?auto=format,compress" },
    { title: "DDANJITRER's AI", thumb: "https://images.prismic.io/alcre/aFUm5Hfc4bHWikLF_flow_2025-06-20_18317930.png?auto=format,compress" },
    { title: "LANEIGE / Cream Skin", thumb: "https://images.prismic.io/alcre/aFNpVbNJEFaPYFh0_6.png?auto=format,compress" },
    { title: "VITAL BEUTY / Meta Green", thumb: "https://images.prismic.io/alcre/aFNparNJEFaPYFh1_7.png?auto=format,compress" },
    { title: "SK Telecom :/AI Help you?", thumb: "https://images.prismic.io/alcre/aFNo3LNJEFaPYFhw_8.png?auto=format,compress" },
    { title: "Always I Love You", thumb: "https://images.prismic.io/alcre/aFNpgbNJEFaPYFh2_9.png?auto=format,compress" },
    { title: "AESTURA / Pop-Up Store", thumb: "https://images.prismic.io/alcre/aFJQ17NJEFaPYDMC_%EB%A6%AC%EC%A0%9C%EB%8D%A4%ED%95%98%EC%9A%B0%EC%8A%A4.jpg?auto=compress,format" },
    { title: "BTS UNIVERSE", thumb: "https://images.prismic.io/alcre/ae7f7d37-e471-4344-b6b3-590ec27def86_0801.webp?auto=compress,format" },
    { title: "SK Telecom WE_ING", thumb: "https://images.prismic.io/alcre/403aff5c-6944-4738-b61f-c80b4265a0d0_pr0901.webp?auto=format,compress" },
];

export default function ReelsSection() {
    const trackRef = useRef<HTMLDivElement>(null);
    const titleRef = useRef<HTMLDivElement>(null);
    const tickerRef = useRef<HTMLDivElement>(null);
    const [activeTitle, setActiveTitle] = useState(reelsWorks[0].title);

    useEffect(() => {
        const track = trackRef.current;
        const ticker = tickerRef.current;
        if (!track || !ticker) return;

        const REELS_N = reelsWorks.length;
        const REELS_GAP = 10;

        function measure() {
            const vh = window.innerHeight;
            const rch = vh * 0.60;
            const rcw = rch * (9 / 16);
            const cards = track!.querySelectorAll('.zc-reels-card');

            cards.forEach(c => {
                (c as HTMLElement).style.width = rcw + 'px';
                (c as HTMLElement).style.height = rch + 'px';
            });

            const rtotalW = REELS_N * (rcw + REELS_GAP) - REELS_GAP;
            const rStartX = (rtotalW - rcw) / 2;
            const rEndX = (rtotalW - rcw) / 2 - (REELS_N - 1) * (rcw + REELS_GAP);
            const rscrollDist = rStartX - rEndX;

            track!.style.width = rtotalW + 'px';
            gsap.set(track, { x: rStartX });

            // Ticks
            const ticks = ticker!.querySelectorAll('.zc-reels-tick');
            ticks.forEach((t, i) => {
                const mid = (REELS_N - 1) / 2;
                const dist = Math.abs(i - mid) / mid;
                const h = Math.round(36 - dist * 20);
                (t as HTMLElement).style.height = h + 'px';
            });

            return { rcw, rch, rtotalW, rStartX, rEndX, rscrollDist };
        }

        let dims = measure();

        const st = gsap.fromTo(track,
            { x: dims.rStartX },
            {
                x: dims.rEndX,
                ease: 'none',
                scrollTrigger: {
                    trigger: '#reelsPinWrap',
                    pin: true,
                    start: 'top top',
                    end: () => `+=${dims.rscrollDist}`,
                    scrub: 1,
                    pinSpacing: true,
                }
            }
        );

        // rAF for tilt/scale/opacity
        const TILT_MAX = 14;
        const SCALE_CTR = 1.06;
        const SCALE_EDGE = 0.78;
        const OPACITY_CTR = 1;
        const OPACITY_EDGE = 0.5;
        const FALLOFF = 1.1;

        let lastActive = -1;
        let rafId: number;

        function reelsRaf() {
            const x = gsap.getProperty(track, 'x') as number;
            const vw = window.innerWidth;
            const cx = vw / 2;
            const cards = track!.querySelectorAll('.zc-reels-card');
            let closestD = Infinity;
            let activeIdx = 0;

            cards.forEach((card, i) => {
                const cardCx = x + i * (dims.rcw + REELS_GAP) + dims.rcw / 2 + (vw - dims.rtotalW) / 2;
                const d = (cardCx - cx) / (vw * FALLOFF);
                const dC = Math.max(-1, Math.min(1, d));
                const tilt = dC * TILT_MAX;
                const absD = Math.abs(dC);
                const scale = SCALE_CTR - (SCALE_CTR - SCALE_EDGE) * absD;
                const opacity = OPACITY_CTR - (OPACITY_CTR - OPACITY_EDGE) * absD;

                const el = card as HTMLElement;
                el.style.transformOrigin = '50% 100%';
                el.style.transform = `rotate(${tilt}deg) scale(${scale})`;
                el.style.opacity = String(opacity);
                el.style.zIndex = String(Math.round(50 - absD * 40));

                const realD = Math.abs(cardCx - cx);
                if (realD < closestD) { closestD = realD; activeIdx = i; }
            });

            if (activeIdx !== lastActive) {
                lastActive = activeIdx;
                setActiveTitle(reelsWorks[activeIdx].title);
                const ticks = ticker!.querySelectorAll('.zc-reels-tick');
                ticks.forEach((t, i) => t.classList.toggle('active', i === activeIdx));
            }

            rafId = requestAnimationFrame(reelsRaf);
        }
        rafId = requestAnimationFrame(reelsRaf);

        const handleResize = () => {
            if (st.scrollTrigger) st.scrollTrigger.kill();
            dims = measure();
            gsap.fromTo(track,
                { x: dims.rStartX },
                {
                    x: dims.rEndX,
                    ease: 'none',
                    scrollTrigger: {
                        trigger: '#reelsPinWrap',
                        pin: true,
                        start: 'top top',
                        end: () => `+=${dims.rscrollDist}`,
                        scrub: 1,
                        pinSpacing: true,
                    }
                }
            );
        };

        window.addEventListener('resize', handleResize);

        return () => {
            cancelAnimationFrame(rafId);
            if (st.scrollTrigger) st.scrollTrigger.kill();
            window.removeEventListener('resize', handleResize);
        };
    }, []);

    return (
        <section className="zc-reels-section" id="reels-content">
            <h2 className="zc-section-label">Reels Content</h2>
            <div className="zc-reels-pin-wrap" id="reelsPinWrap">
                <div className="zc-reels-scene-title" ref={titleRef}>{activeTitle}</div>
                <div className="zc-reels-track-outer">
                    <div className="zc-reels-track" ref={trackRef}>
                        {reelsWorks.map((w, i) => (
                            <div className="zc-reels-card" key={i}>
                                <img src={w.thumb} alt={w.title} loading={i < 6 ? 'eager' : 'lazy'} />
                            </div>
                        ))}
                    </div>
                </div>
                <div className="zc-reels-ticker-wrap" ref={tickerRef}>
                    {reelsWorks.map((_, i) => (
                        <div className="zc-reels-tick" key={i} />
                    ))}
                </div>
            </div>
        </section>
    );
}

'use client';

import { useEffect, useRef } from 'react';
import gsap from 'gsap';
import SplitType from 'split-type';

const members = [
    { name: 'Sudeep', img: '/assets/showcase/img1.jpg' },
    { name: 'Rahul', img: '/assets/showcase/img2.jpg' },
    { name: 'Priya', img: '/assets/showcase/img3.jpg' },
    { name: 'Amit', img: '/assets/showcase/img4.jpg' },
    { name: 'Sneha', img: '/assets/showcase/img5.jpg' },
];

export default function TeamSection() {
    const sectionRef = useRef<HTMLElement>(null);

    useEffect(() => {
        if (!sectionRef.current) return;

        // Split all name headings
        const nameEls = sectionRef.current.querySelectorAll('.zc-name');
        nameEls.forEach((el) => {
            const h1 = el.querySelector('h1');
            if (h1) new SplitType(h1 as HTMLElement, { types: 'chars' });
        });

        const defaultChars = nameEls[0]?.querySelectorAll('.char');
        if (defaultChars) gsap.set(defaultChars, { y: '0%' });

        nameEls.forEach((el, i) => {
            if (i > 0) gsap.set(el.querySelectorAll('.char'), { y: '100%' });
        });

        const imgs = sectionRef.current.querySelectorAll('.zc-img');
        imgs.forEach((img, index) => {
            const nameEl = nameEls[index + 1];
            if (!nameEl) return;
            const chars = nameEl.querySelectorAll('.char');

            img.addEventListener('mouseenter', () => {
                gsap.to(img, { width: 130, height: 130, duration: 0.5, ease: 'power4.out' });
                gsap.to(defaultChars!, { y: '-100%', duration: 0.5, ease: 'power4.out', stagger: { each: 0.02, from: 'center' } });
                gsap.to(chars, { y: '0%', duration: 0.6, ease: 'power4.out', stagger: { each: 0.02, from: 'center' }, overwrite: true });
            });

            img.addEventListener('mouseleave', () => {
                gsap.to(img, { width: 70, height: 70, duration: 0.5, ease: 'power4.out' });
                gsap.to(chars, { y: '100%', duration: 0.5, ease: 'power4.out', stagger: { each: 0.02, from: 'center' } });
                gsap.to(defaultChars!, { y: '0%', duration: 0.6, ease: 'power4.out', stagger: { each: 0.02, from: 'center' }, overwrite: true });
            });
        });
    }, []);

    return (
        <section className="zc-team" id="about" ref={sectionRef}>
            <h2 className="zc-section-label" style={{ color: '#e3e3db' }}>The Founders</h2>
            <div className="zc-profile-images">
                {members.map((m, i) => (
                    <div className="zc-img" key={i}>
                        <img src={m.img} alt={m.name} />
                    </div>
                ))}
            </div>
            <div className="zc-profile-names">
                <div className="zc-name default">
                    <h1>The Squad</h1>
                </div>
                {members.map((m, i) => (
                    <div className="zc-name" key={i}>
                        <h1>{m.name}</h1>
                    </div>
                ))}
            </div>
        </section>
    );
}

import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';

const HERO_SCROLL_PAGES = 2.5; // how many viewports of scroll the 3D hero uses

/**
 * Drop-in replacement for drei's useScroll().
 * Reads window.scrollY instead of a nested ScrollControls container,
 * so the whole page shares one scrollbar.
 */
export function usePageScroll() {
    const ref = useRef<{
        offset: number;
        range: (from: number, distance: number) => number;
    }>({
        offset: 0,    // 0ΓÇæ1 over the hero zone
        range: (from: number, distance: number) => 0,
    });

    useFrame(() => {
        const vh = window.innerHeight;
        const heroScrollHeight = vh * HERO_SCROLL_PAGES;
        const scrollY = window.scrollY;

        // clamp offset 0-1 within the hero zone
        const offset = Math.min(1, Math.max(0, scrollY / heroScrollHeight));
        ref.current.offset = offset;

        ref.current.range = (from: number, distance: number) => {
            const start = from;
            const end = from + distance;
            if (offset <= start) return 0;
            if (offset >= end) return 1;
            return (offset - start) / distance;
        };
    });

    return ref.current;
}

export { HERO_SCROLL_PAGES };
